CREATE TABLE tracking_links (token_hash TEXT PRIMARY KEY, record_id TEXT UNIQUE NOT NULL REFERENCES records(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT, record_id TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, at TEXT NOT NULL);
CREATE INDEX audit_time ON audit_events(at);
CREATE TABLE password_resets (id TEXT PRIMARY KEY, user_key TEXT UNIQUE NOT NULL, code_hash TEXT NOT NULL, expires INTEGER NOT NULL, tries INTEGER NOT NULL DEFAULT 0);
